import{_ as a,C as r,o as n,c as s,a2 as t,E as l}from"./chunks/framework.CdvW4CUT.js";const f=JSON.parse('{"title":"Help","description":"","frontmatter":{"title":"Help"},"headers":[],"relativePath":"en/guide/help.md","filePath":"en/guide/help.md"}'),i={name:"en/guide/help.md"};function h(c,e,d,p,u,g){const o=r("Capture");return n(),s("div",null,[e[0]||(e[0]=t('<h1 id="help" tabindex="-1">Help <a class="header-anchor" href="#help" aria-label="Permalink to &quot;Help&quot;">​</a></h1><p>Kessho&#39;s help is a window that presents some of the tools your AI agents can call in the memory. It opens from the sidebar, over the current screen, and changes nothing in your memory.</p><h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><p>Click <strong>Help</strong> at the bottom of the sidebar, next to <strong>Settings</strong>. The <strong>Kessho Help &amp; MCP Tools Center</strong> window opens.</p><ul><li><strong>The title and its subtitle</strong>: &quot;Catalog of tools exposed by the embedded MCP server&quot;.</li><li><strong>The search field</strong>: &quot;Search MCP tool (e.g. mem_recall, health)...&quot;.</li><li><strong>The families</strong>, as pills: <strong>All</strong>, <strong>Memory &amp; Recall</strong>, <strong>Health &amp; Integrity</strong>, <strong>CLI Connectors</strong> and <strong>Governance</strong>.</li><li><strong>The tool list</strong>: for each one, its name, its family, a sentence saying what it is for and an example call (&quot;Usage: …&quot;, shown as is).</li><li><strong>A ✕ button</strong>, top right, to close.</li></ul><p>This list is a preview: about ten tools, not all of them. The complete, up-to-date list is in the <a href="/en/reference/mcp/">MCP reference</a>.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><h3 id="open-the-help" tabindex="-1">Open the help <a class="header-anchor" href="#open-the-help" aria-label="Permalink to &quot;Open the help&quot;">​</a></h3><p>Click <strong>Help</strong> in the sidebar. When the sidebar is collapsed, the button keeps its icon (a question mark) and its <strong>Help</strong> tooltip.</p><h3 id="search-for-a-tool" tabindex="-1">Search for a tool <a class="header-anchor" href="#search-for-a-tool" aria-label="Permalink to &quot;Search for a tool&quot;">​</a></h3><p>Type in the search field. The list narrows to the tools whose name or description contains your text, ignoring case. If nothing matches, the window says &quot;No MCP tool matches your search.&quot;</p>',11)),l(o,{name:"aide",alt:'The Help and MCP tools center: the catalog of tools exposed to agents, filtered by the typed "health".'}),e[1]||(e[1]=t('<h3 id="filter-by-family" tabindex="-1">Filter by family <a class="header-anchor" href="#filter-by-family" aria-label="Permalink to &quot;Filter by family&quot;">​</a></h3><p>Click a family to keep only its tools; <strong>All</strong> shows them again. The search and the family combine.</p><h3 id="close-the-window" tabindex="-1">Close the window <a class="header-anchor" href="#close-the-window" aria-label="Permalink to &quot;Close the window&quot;">​</a></h3><p>Click the <strong>✕</strong>, or click outside the window, on the backdrop.</p><h3 id="go-further" tabindex="-1">Go further <a class="header-anchor" href="#go-further" aria-label="Permalink to &quot;Go further&quot;">​</a></h3><ul><li>To learn how to ask an agent for these tools, see <a href="/en/guide/agents.html">Connect your agents</a>.</li><li>For the detail of each tool, its parameters and examples, see the <a href="/en/reference/mcp/">MCP reference</a>.</li></ul>',6))])}const y=a(i,[["render",h]]);export{f as __pageData,y as default};
